// ui/routes/settings/notifications-and-onboarding.mjs — feature "settings". Generated by tools/split-by-feature.mjs v1;
// the body of register() was moved verbatim from ui/server.mjs. Edit it here from now on.
import { engineReadiness } from '../../../src/core/engines/readiness.mjs';
import { resolveNightConfig } from '../../../src/core/night/config.mjs';
import { nightLayers } from '../../../src/core/night/effective.mjs';
import { listNotifications, markAllRead, markRead, unreadCount } from '../../../src/core/notifications.mjs';
import { onboardingStatus } from '../../../src/core/onboarding.mjs';
import { nightModeHereSince, nightModeHereSinceFor, nightModeSettings, nightModeToggle, nightModeToggleFor, onboardingPrefs, setOnboardingPrefs } from '../../../src/core/settings.mjs';
import { awayPersonOf, badRequest, emitChanged, isFreshInstall, isTruthy, notifReader, pinUiLevel, resolveProjectDir } from '../../server.mjs';

export function register(app) {

// GET /api/notifications?scope=schedule[&unread=1][&problems=1] -> { notifications, unread }
app.get('/api/notifications', (req, res) => {
  try {
    const scope = typeof req.query.scope === 'string' && req.query.scope ? req.query.scope : 'schedule';
    const flag = (v) => v === '1' || v === 'true';
    res.json({
      notifications: listNotifications({ scope, unread: flag(req.query.unread), problems: flag(req.query.problems), reader: notifReader(req) }),
      unread: unreadCount(scope, { reader: notifReader(req) }),
    });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.post('/api/notifications/read-all', (req, res) => {
  const scope = req.body && typeof req.body.scope === 'string' && req.body.scope ? req.body.scope : 'schedule';
  markAllRead(scope, { reader: notifReader(req) });
  emitChanged('notifications-changed');
  res.json({ unread: unreadCount(scope, { reader: notifReader(req) }) });
});

app.post('/api/notifications/:id/read', (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isSafeInteger(id)) return badRequest(res, 'invalid notification id');
  const read = !(req.body && req.body.read === false);
  if (!markRead(id, { read, reader: notifReader(req) })) return res.status(404).json({ error: 'notification not found' });
  emitChanged('notifications-changed');
  res.json({ unread: unreadCount('schedule', { reader: notifReader(req) }) });
});

app.get('/api/engines', async (req, res) => {
  try { res.json({ engines: await engineReadiness({ force: req.query.recheck === '1' }) }); }
  catch (err) { res.status(500).json({ error: String(err?.message || err) }); }
});

app.get('/api/away-mode', (req, res) => {
  const raw = typeof req.query.projectDir === 'string' && req.query.projectDir ? req.query.projectDir : null;
  const projectDir = raw ? resolveProjectDir(raw) : null;          // same key as PATCH /api/config (~ expanded)
  const user = nightModeSettings() || {};
  // B4: with per-person Away mode, the signed-in person's own switch (perPerson names whose).
  const person = awayPersonOf(req);
  const live = {
    toggle: nightModeToggleFor(person), hereSince: nightModeHereSinceFor(person),
    // What a run whose owner never set their own switch follows (the run page's read-only line).
    ...(person ? { perPerson: person, instanceToggle: nightModeToggle(), instanceHereSince: nightModeHereSince() } : {}),
  };
  if (!projectDir) {
    const { config, sources } = resolveNightConfig({ user });
    return res.json({ config, sources, inherited: resolveNightConfig({}), ...live, user, project: null });
  }
  const L = nightLayers(projectDir);
  const { config, sources } = resolveNightConfig(L);
  res.json({ config, sources, inherited: resolveNightConfig({ user: L.user, team: L.team }), ...live, user, project: L.project || {} });
});

// Lightweight sidebar-count snapshot. Three cheap COUNT(*) queries — deliberately NOT
// the full list endpoints, so a navigation/refresh never pulls the (potentially large)
// machine-wide history just to update a badge. Running is derived client-side from the
// in-memory runs map (live via WS), so it is not included here. Synchronous: the three
// helpers are sync getDb().prepare(...).get() calls.
// ---------------------------------------------------------------------------
// Getting started (docs/getting-started.md). GET is the derived checklist —
// eight ticks computed from the store + PATH, never stored — plus the stored flags.
// POST writes ONLY those flags ({hidden?, welcomeSeen?, workspaceGuideSeen?}; booleans; unknown keys
// 400) and answers with the same full payload, so one round trip repaints.
// ---------------------------------------------------------------------------
// ?recheck=1 skips the remembered Claude sign-in answer (the dialog's Check again).
app.get('/api/onboarding', async (req, res) => {
  try { res.json({ ...(await onboardingStatus({ recheck: isTruthy(req.query.recheck) })), fresh: isFreshInstall() }); }
  catch (err) { res.status(500).json({ error: err && err.message ? err.message : String(err) }); }
});
app.post('/api/onboarding', async (req, res) => {
  try {
    await pinUiLevel();                        // before welcomeSeen flips and ends "fresh install"
    await setOnboardingPrefs(req.body || {});
  }
  catch (err) { return badRequest(res, err && err.message ? err.message : String(err)); }
  emitChanged('onboarding-changed');
  try { res.json({ ...(await onboardingStatus()), fresh: isFreshInstall() }); }
  catch (err) { res.status(500).json({ error: err && err.message ? err.message : String(err), ...onboardingPrefs() }); }
});
}
